68	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], runePremium);
69	  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
70	  const firstInsuranceSurcharge = policyBasePremium / 10;
71	  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
72	};
